-- ============================================================================
-- 0322 — International: oncology and radiology, treatment guides, machines
-- ============================================================================
-- AFTER 0321. Safe to re-run.
--
-- Asked 4 Nov 2026: add radiology and chemotherapy (oncology); give every
-- treatment something to read — how it is done, preparation and precautions,
-- life after, do's and don'ts — and show pictures of the major machines.
--
--   intl_procedures   + chemotherapy, radiotherapy, MRI, CT and PET-CT scans;
--                     guide jsonb: {about, before[], after[], dos[], donts[], machines[]}.
--   intl_machines     the machines, each with a short plain explanation, the
--                     scene its AI picture is made from, and image_url (filled
--                     by the intl-article-image function, kind 'machine').
--   sehat_intl_catalogue()  now returns guide per procedure and the machines.
--
-- Content: supabase/reference/intl-treatment-guides.json (general information
-- by the Sehatsandhi team, not medical advice).
-- ============================================================================

insert into intl_procedures (code, name, speciality, grp, hospital_days, india_days, summary, reports, sort) values
  ('chemotherapy', 'Chemotherapy (per cycle)', 'Oncology', 'complex', 0, 21, 'Cancer medicines given by drip or tablets in planned cycles, usually in a day-care unit, under a medical oncologist.', 'Biopsy and histopathology report, PET-CT or CT scans, blood counts, kidney and liver tests, treatment history and any previous chemotherapy details', 345),
  ('radiotherapy', 'Radiotherapy (course)', 'Oncology', 'complex', 0, 35, 'High-energy X-rays aimed precisely at a tumour, given in short daily sessions over a few weeks, planned by a radiation oncologist.', 'Biopsy report, recent MRI, CT or PET-CT, surgery notes if operated, previous radiotherapy details', 346),
  ('mri_scan', 'MRI scan', 'Radiology', 'routine', 0, 2, 'Detailed pictures of the brain, spine, joints and organs using a strong magnet and radio waves — no X-rays.', 'The doctor''s referral or question, previous scans, a list of any metal implants, pacemaker or devices in the body', 360),
  ('ct_scan', 'CT scan', 'Radiology', 'routine', 0, 2, 'Fast, detailed cross-section X-ray pictures of the body, often with a contrast dye.', 'The doctor''s referral, previous scans, kidney function test if contrast is planned, allergy history', 361),
  ('pet_ct', 'PET-CT scan', 'Radiology', 'routine', 0, 3, 'A whole-body scan that shows how active tissues are, mainly used to find, stage and follow up cancer.', 'Biopsy report, previous scans, blood sugar readings (diabetes affects this scan), treatment history', 362)
on conflict (code) do update set name = excluded.name, speciality = excluded.speciality, grp = excluded.grp,
  hospital_days = excluded.hospital_days, india_days = excluded.india_days, summary = excluded.summary,
  reports = excluded.reports, sort = excluded.sort;

alter table intl_procedures add column if not exists guide jsonb;

create table if not exists intl_machines (
  key text primary key,
  name text not null,
  what text not null,
  scene text,
  image_url text check (image_url is null or image_url ~ '^https://'),
  sort integer not null default 100,
  active boolean not null default true
);
alter table intl_machines enable row level security;
drop policy if exists intl_machines_read on intl_machines;
create policy intl_machines_read on intl_machines for select using (true);
drop policy if exists intl_machines_admin on intl_machines;
create policy intl_machines_admin on intl_machines for all to authenticated using (sehat_is_admin()) with check (sehat_is_admin());
grant select on intl_machines to anon, authenticated;
grant insert, update, delete on intl_machines to authenticated;

insert into intl_machines (key, name, what, scene, sort) values
  ('mri', 'MRI scanner', 'A large tube-shaped magnet that makes detailed pictures without X-rays. The scan is painless but loud; you lie still for 20–45 minutes.', 'A modern MRI scanner in a clean, bright hospital imaging room, white tunnel-shaped machine with a patient table, no people', 10),
  ('ct', 'CT scanner', 'A ring-shaped X-ray machine that takes cross-section pictures in a few minutes. You lie on a table that moves through the ring.', 'A modern CT scanner with its ring-shaped gantry and patient table in a clean hospital imaging room, no people', 20),
  ('pet_ct', 'PET-CT scanner', 'A CT scanner combined with a PET camera that detects a small dose of tracer, showing which tissues are most active.', 'A PET-CT scanner with a long gantry and patient table in a calm nuclear medicine room with soft lighting, no people', 30),
  ('linac', 'Linear accelerator (radiotherapy)', 'The machine that gives radiotherapy. It rotates around you and shapes the beam to the tumour; each session takes minutes and does not hurt.', 'A modern radiotherapy linear accelerator machine with a treatment couch in a spacious, softly lit treatment room, no people', 40),
  ('chemo_daycare', 'Chemotherapy day-care unit', 'Comfortable recliner chairs with infusion pumps, where chemotherapy is given by trained oncology nurses.', 'A calm, bright chemotherapy day-care room with comfortable reclining chairs, infusion stands and large windows, no people', 50),
  ('cath_lab', 'Cath lab', 'A special X-ray room where cardiologists look inside heart arteries and place stents through a thin tube in the wrist or groin.', 'A modern cardiac catheterisation lab with a C-shaped X-ray arm, monitors and a patient table, clean and empty', 60),
  ('heart_lung', 'Heart-lung machine', 'Takes over the work of the heart and lungs during open-heart surgery such as bypass or valve replacement, run by a perfusionist.', 'A heart-lung bypass machine with pumps and tubing beside an empty operating table in a modern cardiac operation theatre, no people', 70),
  ('modular_ot', 'Modular operation theatre', 'A sealed operating room with filtered air flowing down over the table, which lowers infection risk for joint and implant surgery.', 'An empty modern modular operation theatre with stainless steel walls, overhead surgical lights and a laminar airflow ceiling', 80),
  ('c_arm', 'C-arm X-ray', 'A mobile X-ray unit used during joint and spine surgery so the surgeon can check implant position in real time.', 'A mobile C-arm X-ray machine standing in an empty modern operation theatre', 90),
  ('laparoscopy', 'Laparoscopy (keyhole surgery) tower', 'A camera and screen system for keyhole surgery through small cuts — less pain and a quicker recovery than open surgery.', 'A laparoscopic surgery tower with a high-definition monitor and camera unit beside an empty operating table', 100),
  ('phaco', 'Phaco machine and operating microscope', 'Used in cataract surgery: the cloudy lens is broken up with ultrasound and removed through a tiny cut, viewed under a microscope.', 'An ophthalmic operating microscope and a phacoemulsification machine in a clean, empty eye operation theatre', 110),
  ('excimer', 'Excimer laser (LASIK)', 'A precise laser that reshapes the front of the eye to correct vision; the treatment itself takes seconds per eye.', 'A modern refractive laser eye surgery machine with a patient bed in a clean, bright clinic room, no people', 120),
  ('cbct', 'Dental CBCT scanner', 'A 3D dental X-ray that shows the jaw bone, so implants can be planned precisely.', 'A modern dental cone beam CT scanner standing in a clean, bright dental clinic room, no people', 130),
  ('ivf_lab', 'IVF laboratory', 'A controlled lab with incubators and microscopes where eggs are fertilised and embryos grow before transfer.', 'A clean IVF embryology laboratory with incubators, an inverted microscope and a laminar flow workstation, soft lighting, no people', 140),
  ('lithotripsy', 'Lithotripsy and urology laser', 'Breaks kidney stones into small pieces with shock waves or a laser, often without any cut.', 'A modern lithotripsy machine with a patient table in a clean urology procedure room, no people', 150),
  ('ultrasound', 'Ultrasound and Doppler', 'Uses sound waves to see organs, blood flow and veins — painless and without radiation.', 'A modern ultrasound machine with a screen and probe beside an examination bed in a bright clinic room, no people', 160)
on conflict (key) do update set name = excluded.name, what = excluded.what, scene = excluded.scene, sort = excluded.sort;

update intl_procedures set guide = $j${"machines": ["phaco"], "about": "The surgeon makes a tiny cut, breaks up the cloudy lens with ultrasound and places a clear artificial lens. It usually takes under half an hour under numbing drops.", "before": ["A full eye check and lens measurement (biometry)", "Control blood sugar and blood pressure", "Tell the doctor about blood thinners and eye drops you use"], "after": ["Vision clears over a few days to weeks", "Use the prescribed drops exactly as advised", "Most people return to daily activities within days; glasses may be updated after a few weeks"], "dos": ["Wear the eye shield at night for the first week", "Keep follow-up visits", "Wash hands before using drops", "Wear sunglasses outdoors"], "donts": ["Do not rub or press the eye", "Avoid swimming and dusty places for 2 weeks", "Avoid eye make-up for a few weeks", "Do not lift heavy weights in the first week"]}$j$::jsonb where code = 'cataract';
update intl_procedures set guide = $j${"machines": ["excimer"], "about": "A laser reshapes the front surface of the eye (cornea) to reduce dependence on glasses. Not every eye is suitable; tests decide.", "before": ["Stop soft contact lenses about a week before (hard lenses longer) for accurate tests", "Corneal thickness and shape tests", "No eye make-up on the day"], "after": ["Mild grittiness for a day or two", "Vision usually improves within days", "Dry eyes are common for a few weeks"], "dos": ["Use lubricating and prescribed drops", "Wear eye shields while sleeping for a few nights", "Attend the next-day check"], "donts": ["Do not rub your eyes", "No swimming for 2 weeks", "Avoid screens for long stretches in the first days"]}$j$::jsonb where code = 'lasik';
update intl_procedures set guide = $j${"machines": [], "about": "Surgery creates a new drainage path (or places a small device) to lower eye pressure when drops or laser are not enough. It aims to protect remaining vision; lost vision does not come back.", "before": ["Eye pressure, visual field and OCT tests", "List of all glaucoma drops", "Control blood sugar and blood pressure"], "after": ["Frequent check-ups in the first weeks", "Drops are adjusted over time", "Vision may be blurred for a few weeks"], "dos": ["Keep every follow-up", "Use drops exactly as told", "Protect the eye at night"], "donts": ["Do not bend low or lift heavy weights early on", "Do not rub the eye", "Do not stop drops without advice"]}$j$::jsonb where code = 'glaucoma';
update intl_procedures set guide = $j${"machines": ["cbct"], "about": "A titanium post is placed in the jaw bone and, after it bonds, holds a crown. Some cases need bone grafting or two visits.", "before": ["Dental X-ray or 3D CBCT scan", "Treat gum disease first", "Tell the dentist about smoking, diabetes and medicines"], "after": ["Mild swelling for a few days", "Soft food for a week or two", "The final crown is fitted once the implant settles"], "dos": ["Rinse gently as advised", "Clean around the implant carefully", "Keep dental check-ups"], "donts": ["Do not smoke — it slows healing", "Avoid hard and very hot food early on", "Do not chew on the implant side before advised"]}$j$::jsonb where code = 'dental_implant';
update intl_procedures set guide = $j${"machines": ["cbct"], "about": "Damaged teeth are saved with root canal treatment and protected with crowns, or gaps filled with bridges.", "before": ["Dental X-rays", "Tell the dentist about sensitivity and medicines"], "after": ["Mild tenderness for a few days", "Temporary crowns are replaced with permanent ones"], "dos": ["Brush and floss daily", "Use a night guard if you grind your teeth"], "donts": ["Do not bite hard objects on new crowns", "Avoid sticky sweets on temporary crowns"]}$j$::jsonb where code = 'dental_smile';
update intl_procedures set guide = $j${"machines": ["laparoscopy"], "about": "The weak spot in the abdominal wall is repaired, usually with a mesh, often by keyhole surgery.", "before": ["Blood tests and ECG", "Stop blood thinners only if your doctor says so", "Fasting from midnight"], "after": ["Walking the same day", "Light work in 1–2 weeks", "Full exercise in 4–6 weeks"], "dos": ["Support the wound when coughing", "Eat fibre and drink water to avoid straining", "Walk daily"], "donts": ["No heavy lifting for 4–6 weeks", "Do not strain on the toilet", "Do not drive while on strong pain medicines"]}$j$::jsonb where code = 'hernia';
update intl_procedures set guide = $j${"machines": ["laparoscopy", "ultrasound"], "about": "The gallbladder is removed through small cuts (laparoscopic cholecystectomy). People live normally without it.", "before": ["Ultrasound and liver tests", "Fasting before surgery", "Medicine list"], "after": ["Home in a day or two", "Shoulder-tip pain from the gas settles in days", "Normal diet gradually"], "dos": ["Small, low-fat meals at first", "Walk daily", "Keep wounds clean and dry"], "donts": ["Avoid heavy, oily food for a few weeks", "No heavy lifting for 2–4 weeks"]}$j$::jsonb where code = 'gallbladder';
update intl_procedures set guide = $j${"machines": [], "about": "Piles, fissures or fistulas are treated with laser or surgery, depending on type and grade.", "before": ["Examination by the surgeon", "Bowel preparation if advised"], "after": ["Discomfort for a few days", "Warm sitz baths help", "Most people return to work within a week"], "dos": ["High-fibre diet and plenty of water", "Sitz baths as advised", "Keep the area clean"], "donts": ["Do not strain or sit long on the toilet", "Avoid spicy food early on", "Do not lift heavy weights for 2 weeks"]}$j$::jsonb where code = 'piles';
update intl_procedures set guide = $j${"machines": ["lithotripsy", "ultrasound"], "about": "Stones are broken with shock waves (ESWL) or a laser through a thin scope, without cuts; large stones may need keyhole surgery.", "before": ["CT scan of the kidneys", "Urine test to rule out infection", "Kidney function test"], "after": ["Stone fragments pass in urine over days", "A small tube (stent) may stay for a few weeks", "Some burning on passing urine at first"], "dos": ["Drink plenty of water", "Keep the stent removal appointment", "Ask about diet to prevent new stones"], "donts": ["Do not ignore fever or severe pain — get help", "Do not cut fluids"]}$j$::jsonb where code = 'kidney_stone';
update intl_procedures set guide = $j${"machines": ["ultrasound"], "about": "Swollen leg veins are closed from inside with laser or radio-frequency heat, through a needle-hole.", "before": ["Doppler ultrasound of the legs"], "after": ["Walking straight away", "Compression stockings for some weeks", "Bruising fades in weeks"], "dos": ["Walk daily", "Wear stockings as advised", "Raise your legs when resting"], "donts": ["Avoid standing still for long", "No hot baths or saunas for a few weeks"]}$j$::jsonb where code = 'varicose';
update intl_procedures set guide = $j${"machines": [], "about": "Endoscopic sinus surgery, septoplasty or tonsil removal is done through the nose or mouth, with no outside cut.", "before": ["CT scan of the sinuses", "ENT examination"], "after": ["Blocked nose for a week or two", "Saline rinses help healing", "Throat pain after tonsil removal for 1–2 weeks"], "dos": ["Use saline rinses as advised", "Sleep with the head raised", "Soft, cool food after tonsil surgery"], "donts": ["Do not blow the nose hard", "Avoid flying for the advised period", "No heavy exercise for 2 weeks"]}$j$::jsonb where code = 'ent_sinus';
update intl_procedures set guide = $j${"machines": ["ultrasound", "ct"], "about": "A planned set of blood tests, scans and doctor consultations, usually in one or two days, with reports explained.", "before": ["Fast overnight if blood sugar and cholesterol tests are planned", "Bring previous reports and medicine list"], "after": ["Reports explained the same or next day", "A doctor advises on any follow-up"], "dos": ["Ask questions about any result", "Share reports with your own doctor"], "donts": ["Do not stop medicines before tests unless told"]}$j$::jsonb where code = 'health_checkup';
update intl_procedures set guide = $j${"machines": ["modular_ot", "c_arm"], "about": "The worn surfaces of the knee are replaced with metal and plastic parts. Most people stand the next day with support.", "before": ["Standing X-ray, blood tests, ECG", "Control sugar and blood pressure", "Prepare home: clear rugs, firm chair"], "after": ["Physiotherapy every day", "Walker or stick for a few weeks", "Most daily activities in 6–12 weeks"], "dos": ["Do the exercises every day", "Keep the wound dry and clean", "Walk little and often"], "donts": ["Do not kneel or squat early on", "No long sitting with the knee bent", "Do not skip blood-thinner doses if prescribed"]}$j$::jsonb where code = 'knee_replacement';
update intl_procedures set guide = $j${"machines": ["modular_ot", "c_arm"], "about": "The damaged hip joint is replaced with an implant. Walking starts within a day or two.", "before": ["X-rays, blood tests, ECG", "Arrange a raised toilet seat and firm chair"], "after": ["Physiotherapy daily", "Hip precautions for about 6 weeks", "Normal walking in weeks to months"], "dos": ["Follow hip precautions", "Use a raised seat", "Walk daily"], "donts": ["Do not cross your legs", "Do not bend the hip beyond 90 degrees early on", "Avoid low chairs"]}$j$::jsonb where code = 'hip_replacement';
update intl_procedures set guide = $j${"machines": ["modular_ot"], "about": "A camera and small tools repair torn tissue inside the joint through small cuts.", "before": ["MRI of the joint", "Blood tests"], "after": ["Sling or brace for some weeks", "Physiotherapy is key"], "dos": ["Ice and rest as advised", "Do your physiotherapy"], "donts": ["Do not lift with the operated arm early on", "Do not remove the sling before advised"]}$j$::jsonb where code = 'shoulder_arthroscopy';
update intl_procedures set guide = $j${"machines": ["c_arm", "mri"], "about": "The part of a disc pressing on a nerve is removed, often through a small cut with a microscope or endoscope.", "before": ["MRI of the spine", "Nerve tests if advised"], "after": ["Walking the same or next day", "Leg pain usually eases soon", "Back exercises after a few weeks"], "dos": ["Walk regularly", "Keep good posture", "Learn safe lifting"], "donts": ["Do not bend and twist", "No heavy lifting for 6 weeks", "Avoid long car journeys early on"]}$j$::jsonb where code = 'spine_disc';
update intl_procedures set guide = $j${"machines": ["c_arm", "modular_ot", "mri"], "about": "Two or more spinal bones are joined with screws, rods and bone graft to stop painful movement or correct shape.", "before": ["MRI, CT and X-rays", "Stop smoking — it affects bone healing", "Medicine review"], "after": ["Hospital stay of several days", "A brace may be advised", "Fusion takes months"], "dos": ["Walk short distances often", "Follow the brace and lifting rules", "Keep follow-up X-rays"], "donts": ["Do not smoke", "No bending, lifting or twisting early on", "Do not take anti-inflammatory painkillers unless prescribed"]}$j$::jsonb where code = 'spine_fusion';
update intl_procedures set guide = $j${"machines": ["laparoscopy"], "about": "The uterus is removed, often by keyhole surgery. Ovaries may or may not be removed — discuss with your surgeon.", "before": ["Pelvic ultrasound and blood tests", "Discuss what will be removed and why"], "after": ["Home in 1–3 days", "Light activity for 2 weeks", "Full recovery in 4–6 weeks"], "dos": ["Walk daily", "Rest, but avoid long bed rest", "Report fever or heavy bleeding"], "donts": ["No heavy lifting for 6 weeks", "No intercourse for about 6 weeks", "Do not drive until comfortable braking"]}$j$::jsonb where code = 'hysterectomy';
update intl_procedures set guide = $j${"machines": ["ivf_lab", "ultrasound"], "about": "Hormone injections stimulate the ovaries, eggs are collected and fertilised in the lab, and an embryo is placed in the uterus.", "before": ["Hormone tests (AMH, FSH) and semen analysis", "Ultrasound scans", "Read the legal notes on IVF in India"], "after": ["A pregnancy test about two weeks after transfer", "Light activity is fine", "Not every cycle succeeds — ask about your chances"], "dos": ["Take medicines exactly on time", "Eat well and rest", "Keep scan appointments"], "donts": ["Do not smoke or drink alcohol", "Avoid very strenuous exercise", "Do not ask for sex selection — it is illegal"]}$j$::jsonb where code = 'ivf';
update intl_procedures set guide = $j${"machines": ["cath_lab"], "about": "A narrowed heart artery is opened with a balloon through a thin tube in the wrist or groin, and a stent keeps it open.", "before": ["Angiography report or CD, echo, ECG", "Kidney function test", "Medicine list"], "after": ["Home in a day or two", "Blood thinners for months", "Cardiac rehabilitation helps"], "dos": ["Take blood thinners without missing a dose", "Heart-healthy diet and daily walking", "Carry your stent card"], "donts": ["Never stop blood thinners without your cardiologist", "Do not smoke", "No heavy lifting for a week"]}$j$::jsonb where code = 'angioplasty';
update intl_procedures set guide = $j${"machines": ["lithotripsy"], "about": "The part of an enlarged prostate blocking urine flow is removed through the urine passage with a scope or laser.", "before": ["PSA test, ultrasound, urine flow test", "Urine infection treated first"], "after": ["A catheter for a day or two", "Some blood in urine for a few weeks", "Urine flow improves"], "dos": ["Drink plenty of water", "Report fever or heavy bleeding"], "donts": ["Do not strain or lift heavy weights for 4 weeks", "Avoid cycling early on"]}$j$::jsonb where code = 'prostate';
update intl_procedures set guide = $j${"machines": ["ultrasound"], "about": "Part or all of the thyroid gland is removed through a small cut in the neck.", "before": ["Thyroid ultrasound and blood tests", "FNAC report if done", "Voice check"], "after": ["Mild neck discomfort and hoarse voice for a short time", "Thyroid tablets may be needed for life"], "dos": ["Take thyroid and calcium tablets exactly as prescribed", "Report tingling in fingers or lips"], "donts": ["Do not stop thyroid tablets", "Avoid heavy neck strain for 2 weeks"]}$j$::jsonb where code = 'thyroid';
update intl_procedures set guide = $j${"machines": ["laparoscopy"], "about": "Keyhole surgery makes the stomach smaller (sleeve) or changes the food route (bypass) to support long-term weight loss.", "before": ["Weight, blood tests, sleep study if advised", "Dietitian and psychology assessment", "A pre-operative diet"], "after": ["Liquid then soft diet for weeks", "Lifelong vitamins", "Regular follow-up"], "dos": ["Eat small, slow, protein-first meals", "Take vitamins for life", "Exercise regularly"], "donts": ["Do not drink with meals", "Avoid sugary drinks and alcohol", "Do not skip follow-ups"]}$j$::jsonb where code = 'bariatric';
update intl_procedures set guide = $j${"machines": ["heart_lung", "cath_lab", "modular_ot"], "about": "Blocked heart arteries are bypassed with blood vessels from the chest, leg or arm. The heart-lung machine may support the body during surgery.", "before": ["Angiography, echo, blood tests", "Stop smoking", "Dental check to clear infection"], "after": ["ICU for a day or two, then ward", "Chest bone heals in 6–8 weeks", "Cardiac rehabilitation"], "dos": ["Walk a little more each day", "Take all heart medicines", "Hug a pillow when coughing"], "donts": ["No lifting over 2–3 kg or pushing with arms for 6–8 weeks", "Do not smoke", "Do not drive for 4–6 weeks"]}$j$::jsonb where code = 'heart_bypass';
update intl_procedures set guide = $j${"machines": ["heart_lung", "modular_ot"], "about": "A damaged heart valve is repaired or replaced with a mechanical or tissue valve.", "before": ["Echo and angiography", "Dental check", "Discuss valve type"], "after": ["ICU then ward", "Mechanical valves need lifelong blood thinners with regular tests", "Cardiac rehabilitation"], "dos": ["Keep INR blood tests if on warfarin", "Tell every dentist you have a valve", "Walk daily"], "donts": ["Do not miss blood-thinner doses", "No heavy lifting for 6–8 weeks"]}$j$::jsonb where code = 'heart_valve';
update intl_procedures set guide = $j${"machines": ["mri", "modular_ot"], "about": "A neurosurgical team removes as much of the tumour as is safe, often with navigation and a microscope.", "before": ["MRI with contrast", "Biopsy report if done", "Discuss risks and plan with the surgeon"], "after": ["ICU monitoring first", "Further treatment (radiotherapy, chemotherapy) may follow", "Rehabilitation as needed"], "dos": ["Take seizure and steroid medicines as prescribed", "Rest and build up activity slowly"], "donts": ["Do not drive until cleared", "Do not stop medicines suddenly"]}$j$::jsonb where code = 'brain_tumour';
update intl_procedures set guide = $j${"machines": ["pet_ct", "modular_ot", "laparoscopy"], "about": "The tumour is removed, planned together with medical and radiation oncologists. Further treatment may follow.", "before": ["Biopsy, PET-CT or CT", "Tumour board opinion", "Nutrition check"], "after": ["Recovery depends on the operation", "Histopathology report guides next steps", "Long-term follow-up"], "dos": ["Eat protein-rich food", "Walk daily", "Keep every follow-up scan"], "donts": ["Do not miss follow-ups", "Do not take herbal remedies without telling your oncologist"]}$j$::jsonb where code = 'cancer_surgery';
update intl_procedures set guide = $j${"machines": ["chemo_daycare", "pet_ct"], "about": "Cancer medicines are given in cycles — often every 2–3 weeks — by drip or tablets, usually without staying overnight. The plan depends on the cancer type and stage.", "before": ["Biopsy, scans and blood counts", "Heart, kidney and liver checks", "A dental check and a plan for your stay in India across cycles"], "after": ["Tiredness, nausea or low blood counts are common and managed with medicines", "Blood tests before each cycle", "Response scans after some cycles"], "dos": ["Wash hands often and avoid crowds when counts are low", "Eat small, frequent meals and drink water", "Report fever above 38°C at once"], "donts": ["Do not eat raw or undercooked food", "Do not take other medicines or supplements without asking", "Do not skip blood tests"]}$j$::jsonb where code = 'chemotherapy';
update intl_procedures set guide = $j${"machines": ["linac", "ct"], "about": "A planning CT maps the tumour, then high-energy X-rays from a linear accelerator are given in short daily sessions, usually 5 days a week for a few weeks.", "before": ["Planning CT scan and markings", "Biopsy and scan reports", "Plan to stay for the whole course"], "after": ["Tiredness and skin redness in the treated area are common", "Side effects settle weeks after the course", "Follow-up scans"], "dos": ["Wash treated skin gently with mild soap", "Wear loose cotton clothes", "Drink plenty of water"], "donts": ["Do not apply creams on treated skin unless approved", "Avoid sun on treated skin", "Do not miss sessions"]}$j$::jsonb where code = 'radiotherapy';
update intl_procedures set guide = $j${"machines": ["mri"], "about": "You lie still inside the scanner for 20–45 minutes. It is noisy but painless; earplugs are given. Sometimes a contrast injection is used.", "before": ["Tell staff about pacemakers, implants, metal pieces or pregnancy", "Remove jewellery and metal", "Tell staff if you feel anxious in closed spaces"], "after": ["Go back to normal activities straight away", "Reports usually within a day"], "dos": ["Lie still and follow breathing instructions", "Drink water after contrast"], "donts": ["Do not take any metal into the room"]}$j$::jsonb where code = 'mri_scan';
update intl_procedures set guide = $j${"machines": ["ct"], "about": "A quick X-ray scan, usually a few minutes. A contrast dye may be given by drip or drink.", "before": ["Kidney test if contrast is planned", "Tell staff about allergies, diabetes medicines (metformin) or pregnancy", "Fast a few hours if asked"], "after": ["Normal activities straight away", "Drink extra water after contrast"], "dos": ["Lie still and hold breath when asked"], "donts": ["Do not hide allergy history"]}$j$::jsonb where code = 'ct_scan';
update intl_procedures set guide = $j${"machines": ["pet_ct"], "about": "A small dose of radioactive sugar is injected; after about an hour of rest, the scan takes 20–30 minutes and shows active tissue across the body.", "before": ["Fast for about 6 hours", "Control blood sugar — tell staff if you are diabetic", "Avoid heavy exercise the day before"], "after": ["Drink water to flush the tracer", "Keep a distance from pregnant women and small children for some hours"], "dos": ["Rest quietly while the tracer spreads", "Keep warm"], "donts": ["Do not eat before the scan", "Do not exercise strenuously the day before"]}$j$::jsonb where code = 'pet_ct';
update intl_procedures set guide = $j${"machines": ["modular_ot"], "about": "A kidney from a near-relative living donor is placed in the lower abdomen. Read the legal notes: foreign patients need committee approval.", "before": ["Matching tests for donor and patient", "Legal documents and committee approval", "Full health checks"], "after": ["Several weeks in India for close monitoring", "Lifelong anti-rejection medicines", "Regular blood tests"], "dos": ["Take anti-rejection medicines on time, every day", "Wash hands and avoid infections", "Keep every test"], "donts": ["Never miss a dose", "Do not take any medicine or herbal product without the transplant team"]}$j$::jsonb where code = 'kidney_transplant';
update intl_procedures set guide = $j${"machines": ["modular_ot"], "about": "Part of a liver from a near-relative living donor replaces a failed liver. Read the legal notes: foreign patients need committee approval.", "before": ["Detailed tests for donor and patient", "Legal documents and committee approval"], "after": ["Weeks to months of monitoring", "Lifelong anti-rejection medicines"], "dos": ["Follow the transplant team's diet and medicine plan", "Avoid infections"], "donts": ["Do not drink alcohol", "Do not take medicines without the transplant team"]}$j$::jsonb where code = 'liver_transplant';
update intl_procedures set guide = $j${"machines": ["chemo_daycare"], "about": "After high-dose treatment, healthy blood stem cells are given by drip to rebuild the bone marrow. Read the legal notes.", "before": ["Donor matching (HLA)", "Heart, lung and infection checks"], "after": ["Weeks in a protected ward", "Months of careful follow-up"], "dos": ["Follow infection precautions strictly", "Eat only safe, cooked food"], "donts": ["Avoid crowds and sick people", "Do not skip follow-up tests"]}$j$::jsonb where code = 'bone_marrow';
update intl_procedures set guide = $j${"machines": ["heart_lung", "cath_lab"], "about": "Heart defects present at birth are corrected by surgery or through a catheter, by a paediatric cardiac team.", "before": ["Echo and other heart tests", "Child's weight and growth record"], "after": ["Paediatric ICU care first", "Regular check-ups as the child grows"], "dos": ["Keep vaccinations up to date", "Follow medicine doses carefully"], "donts": ["Do not miss follow-up echoes"]}$j$::jsonb where code = 'child_heart';

create or replace function sehat_intl_catalogue()
returns jsonb language sql stable security definer set search_path = public as $$
  with fee as (select sehat_intl_fee_pct() as pct)
  select jsonb_build_object(
    'fee_pct', (select pct from fee),
    'fx', coalesce((select value::jsonb from site_settings where key = 'intl_fx'), '{}'::jsonb),
    'procedures', coalesce((select jsonb_agg(jsonb_build_object(
        'code', p.code, 'name', p.name, 'speciality', p.speciality, 'grp', p.grp,
        'hospital_days', p.hospital_days, 'india_days', p.india_days, 'summary', p.summary, 'reports', p.reports,
        'legal_title', p.legal_title, 'legal_points', p.legal_points, 'legal_sources', p.legal_sources, 'legal_version', p.legal_version,
        'guide', p.guide)
        order by p.sort) from intl_procedures p where p.active), '[]'::jsonb),
    'machines', coalesce((select jsonb_agg(jsonb_build_object('key', m.key, 'name', m.name, 'what', m.what, 'image_url', m.image_url) order by m.sort)
                          from intl_machines m where m.active), '[]'::jsonb),
    'hospitals', coalesce((select jsonb_agg(jsonb_build_object(
        'id', b.id, 'name', b.name,
        'city', coalesce(nullif(b.own_city, ''), nullif(b.own_district, '')),
        'state', b.own_state,
        'city_level', coalesce(h.city_level, sehat_intl_city_level(coalesce(nullif(b.own_city, ''), b.own_district))),
        'star', h.star, 'nabh', h.nabh, 'jci', h.jci, 'beds', h.beds, 'icu_beds', h.icu_beds,
        'panels', to_jsonb(h.panels), 'languages', to_jsonb(h.languages), 'specialities', to_jsonb(h.specialities),
        'about', h.about, 'photo_url', b.photo_url,
        'cover_path', (select m.path from intl_media m
                       where m.business_id = b.id and m.status = 'approved' and m.kind = 'photo'
                       order by m.sort, m.uploaded_at limit 1),
        'media', coalesce((select jsonb_agg(jsonb_build_object(
            'kind', m.kind, 'path', m.path,
            'youtube_id', m.youtube_id, 'category', m.category, 'caption', m.caption) order by m.sort, m.uploaded_at)
            from intl_media m where m.business_id = b.id and m.status = 'approved'), '[]'::jsonb),
        'nearest_airport', h.nearest_airport, 'airport_hours', h.airport_hours,
        'site_url', (select case when s.tier = 'full' and s.custom_domain is not null then 'https://www.' || s.custom_domain
                                 else '/s/' || s.slug end
                       from business_sites s where s.business_id = b.id and s.is_live),
        'packages', coalesce((select jsonb_agg(jsonb_build_object(
            'procedure_code', k.procedure_code,
            'price_min', (ceil(k.price_min * (1 + (select pct from fee) / 100.0) / 100.0) * 100)::integer,
            'price_max', (ceil(k.price_max * (1 + (select pct from fee) / 100.0) / 100.0) * 100)::integer,
            'room_type', k.room_type, 'included', k.included, 'excluded', k.excluded,
            'hospital_days', k.hospital_days, 'india_days', k.india_days, 'fly_after_days', k.fly_after_days,
            'doctor_name', k.doctor_name, 'valid_until', k.valid_until))
            from intl_packages k where k.business_id = b.id and k.active and k.valid_until >= current_date), '[]'::jsonb))
        order by b.name)
        from intl_hospitals h join businesses b on b.id = h.business_id
        where h.status = 'listed' and b.status = 'active'), '[]'::jsonb)
  )
$$;

notify pgrst, 'reload schema';
